//! A core's CPU state block, shared by both cores (docs/arm64-virt-android16-plan.md
//! P1.0): each core declares its fields with `state!` (the x86 core in
//! cpu::global_pointers, the ARM core in aarch64::state, both generated by
//! gen/state_layout.js). The default build keeps the block at fixed addresses
//! below --global-base (4096), which generated code reads directly. The
//! parallel build (docs/multicore.md) places it in a static instead: every
//! vCPU worker relocates its own copy of the module into the shared memory,
//! and with it this block; generated code of a worker embeds that worker's
//! addresses. Offsets are the same in both. (tools/parallel_wasm.mjs finds the
//! block by the name STATE_BLOCK, which one core has once.)

#[cfg(feature = "parallel")]
#[repr(C, align(64))]
pub struct StateBlock(pub [u8; 4096]);
#[cfg(feature = "parallel")]
pub static mut STATE_BLOCK: StateBlock = StateBlock([0; 4096]);

macro_rules! state {
    ($name:ident: $type:ty = $offset:literal) => {
        #[cfg(not(feature = "parallel"))]
        pub const $name: *mut $type = $offset as *mut $type;
        #[cfg(feature = "parallel")]
        pub const $name: *mut $type = unsafe {
            (&raw mut $crate::state_block::STATE_BLOCK)
                .cast::<u8>()
                .add($offset)
                .cast::<$type>()
        };
    };
}

/// Address of offset 0 of the state layout (src/state_layout.js)
#[no_mangle]
pub fn state_base() -> u32 {
    #[cfg(feature = "parallel")]
    return (&raw mut STATE_BLOCK) as u32;
    #[cfg(not(feature = "parallel"))]
    return 0;
}
